const fontLinks=new Set();
function ensureFont(fi){const f=FONTS[fi];if(!f||!f.g||fontLinks.has(f.g))return;fontLinks.add(f.g);const l=document.createElement('link');l.rel='stylesheet';l.href='https://fonts.googleapis.com/css2?family='+f.g+'&display=swap';document.head.append(l)}
const loadImg=src=>new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=src});
let state={title:'我的旅行手帳',current:0,pages:[{title:'京都，慢慢走。',paper:'grid',items:[{id:'welcome',type:'text',text:'把日子過慢一點，\n把回憶貼近一點。',x:11,y:13,w:390,r:-3},{id:'demo',type:'photo',src:'kyoto.webp',frame:'polaroid',x:12,y:31,w:390,r:-6},{id:'tape1',type:'tape',color:0,x:30,y:29,w:200,r:5},{id:'note1',type:'text',text:'在小巷裡，遇見京都。\n一杯茶，一整個午後。',x:32,y:76,w:320,r:3},{id:'tape2',type:'tape',color:1,x:69,y:66,w:135,r:-28}]}]}, selected=null, db, saveTimer, frame='polaroid';
const page=()=>state.pages[state.current];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function persist(){clearTimeout(saveTimer);$('#saveStatus').textContent='儲存中…';saveTimer=setTimeout(()=>{if(!db){$('#saveStatus').textContent='無法儲存，請匯出留存';return}try{const tx=db.transaction('journal','readwrite');tx.objectStore('journal').put(state,'main');tx.oncomplete=()=>$('#saveStatus').textContent='已儲存在此裝置';tx.onerror=()=>{$('#saveStatus').textContent='儲存失敗';toast('儲存空間不足，請先匯出圖片')}}catch{$('#saveStatus').textContent='儲存失敗，請匯出留存'}},250)}
function tapeStyle(i){const t=TAPES[i]||TAPES[0],[u,w,h]=tapeTile(t.p);return`url("${u}") 0 0/${w}px ${h}px,${t.c}`}
function render(){const p=page();$('#bookTitle').value=state.title;$('#pageTitle').value=p.title;$('#pageNumber').textContent=String(state.current+1).padStart(2,'0')+' / '+String(state.pages.length).padStart(2,'0');$('#pages').replaceChildren();state.pages.forEach((p,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0')+'  '+p.title;b.className=i===state.current?'active':'';b.onclick=()=>{state.current=i;selected=null;render();persist()};$('#pages').append(b)});$('#paper').className='paper '+p.paper;$$('[data-paper]').forEach(b=>b.classList.toggle('selected',b.dataset.paper===p.paper));renderItems()}
function renderItems(){$('#items').replaceChildren();const scale=$('#paper').clientWidth/640;page().items.forEach(i=>{const el=document.createElement('div');el.className='item '+(i.type==='photo'?i.frame:i.type)+(selected===i.id?' selected':'');el.dataset.id=i.id;el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label',i.type==='photo'?'照片：按方向鍵移動':i.type==='tape'?'紙膠帶：按方向鍵移動':i.type==='sticker'?(stickerMap[i.name]?.n||'貼紙')+'貼紙：按方向鍵移動':i.text);Object.assign(el.style,{left:i.x+'%',top:i.y+'%',width:i.w/640*100+'%',transform:`rotate(${i.r}deg)`});if(i.type==='photo'){const img=new Image();img.src=i.src;img.alt=i.id==='demo'?'京都祇園街道示範照片':'我的旅行照片';el.append(img);el.style.padding=i.frame==='polaroid'?`${10*scale}px ${10*scale}px ${32*scale}px`:'0'}if(i.type==='text'){el.textContent=i.text;el.style.fontSize=(i.id==='welcome'?30:21)*scale+'px';const ft=FONTS[i.f||0]||FONTS[0];el.style.fontFamily=ft.f;ensureFont(i.f||0)}if(i.type==='sticker'){el.innerHTML=stickerMarkup(i.name)}if(i.type==='tape'){el.style.background=tapeStyle(i.color);el.style.height=42*scale+'px'}el.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();select(i.id);el.setPointerCapture(e.pointerId);const rect=$('#paper').getBoundingClientRect(),sx=e.clientX,sy=e.clientY,ox=i.x,oy=i.y,[x0,x1,y0,y1]=bounds(i,el,rect);el.onpointermove=ev=>{i.x=clamp(ox+(ev.clientX-sx)/rect.width*100,x0,x1);i.y=clamp(oy+(ev.clientY-sy)/rect.height*100,y0,y1);el.style.left=i.x+'%';el.style.top=i.y+'%'};el.onpointerup=()=>{el.onpointermove=null;persist()};el.onpointercancel=()=>{el.onpointermove=null;persist()}};el.onclick=()=>select(i.id);el.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();select(i.id);const[x0,x1,y0,y1]=bounds(i,el,$('#paper').getBoundingClientRect());i.x=clamp(i.x+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0),x0,x1);i.y=clamp(i.y+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0),y0,y1);el.style.left=i.x+'%';el.style.top=i.y+'%';persist()}};$('#items').append(el)});updateControls()}
function select(id){selected=id;$$('.item').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));updateControls()}
function updateControls(){const i=page().items.find(i=>i.id===selected);$('#selection').hidden=!i;if(i){$('#size').value=i.w;$('#rotation').value=i.r}}
function addItem(item){item.id=crypto.randomUUID();page().items.push({x:20,y:24,w:250,r:-4,...item});selected=item.id;renderItems();persist()}
$('#paper').onclick=e=>{if(e.target.id==='paper')select(null)};
$('#addPage').onclick=()=>{state.pages.push({title:'新的旅途片刻',paper:'grid',items:[]});state.current=state.pages.length-1;selected=null;render();persist()};
$('#bookTitle').oninput=e=>{state.title=e.target.value;persist()};$('#pageTitle').oninput=e=>{page().title=e.target.value;const nav=$('#pages .active');if(nav)nav.textContent=String(state.current+1).padStart(2,'0')+'  '+e.target.value;persist()};
$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));['photo','tape','sticker','text'].forEach(t=>$('#'+t+'-panel').hidden=t!==b.dataset.tab)});
$$('[data-frame]').forEach(b=>b.onclick=()=>{frame=b.dataset.frame;$$('[data-frame]').forEach(x=>x.classList.toggle('selected',x===b));const i=page().items.find(i=>i.id===selected);if(i?.type==='photo'){i.frame=frame;renderItems();persist()}});
$$('[data-paper]').forEach(b=>b.onclick=()=>{page().paper=b.dataset.paper;render();persist()});
TAPES.forEach((t,i)=>{const b=document.createElement('button');b.style.background=tapeStyle(i);b.title=t.n;b.setAttribute('aria-label',t.n+'紙膠帶');b.onclick=()=>addItem({type:'tape',color:i,w:210});$('#tapes').append(b)});
STICKERS.forEach(s=>{const b=document.createElement('button');b.innerHTML=stickerMarkup(s.k);b.title=s.n;b.setAttribute('aria-label',s.n+'貼紙');b.onclick=()=>addItem({type:'sticker',name:s.k,w:110,r:-6});$('#stickers').append(b)});
let textFont=0;
let hoverTimer;
FGROUPS.forEach((g,gi)=>{const idx=FONTS.map((f,i)=>i).filter(i=>FONTS[i].k===gi);if(!idx.length)return;
const h=document.createElement('div');h.className='font-group';h.textContent=g;$('#fonts').append(h);
const wrap=document.createElement('div');wrap.className='font-grid';$('#fonts').append(wrap);
idx.forEach(i=>{const f=FONTS[i],b=document.createElement('button');b.textContent=f.n;b.style.fontFamily=f.f;b.dataset.fi=i;if(i===0)b.className='selected';b.setAttribute('aria-label','字體：'+f.n);
b.onpointerenter=()=>{clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>ensureFont(i),180)};b.onpointerleave=()=>clearTimeout(hoverTimer);b.onfocus=()=>ensureFont(i);
b.onclick=()=>{textFont=i;ensureFont(i);$$('#fonts button').forEach(x=>x.classList.toggle('selected',+x.dataset.fi===i));const it=page().items.find(it=>it.id===selected);if(it&&it.type==='text'){it.f=i;renderItems();persist()}};wrap.append(b)})});
$('#addText').onclick=()=>{const text=$('#note').value.trim();if(!text){toast('先寫下一點文字吧');return}addItem({type:'text',text,w:320,f:textFont});$('#note').value=''};
$('#choosePhoto').onclick=()=>$('#photoInput').click();$('#photoInput').onchange=async e=>{const targetPage=page();for(const file of e.target.files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('請選擇 JPG、PNG 或 WebP 照片');continue}try{const img=await createImageBitmap(file);const c=document.createElement('canvas'),ratio=Math.min(1,1600/Math.max(img.width,img.height));c.width=img.width*ratio;c.height=img.height*ratio;c.getContext('2d').drawImage(img,0,0,c.width,c.height);img.close();const item={id:crypto.randomUUID(),type:'photo',src:c.toDataURL('image/jpeg',.85),frame,x:18,y:22,w:290,r:-4};targetPage.items.push(item);if(page()===targetPage){selected=item.id;renderItems()}persist()}catch{toast('這張照片無法讀取，請換一張試試')}}e.target.value=''};
$('#size').oninput=e=>{const i=page().items.find(i=>i.id===selected);if(i){i.w=+e.target.value;renderItems();persist()}};$('#rotation').oninput=e=>{const i=page().items.find(i=>i.id===selected);if(i){i.r=+e.target.value;renderItems();persist()}};$('#remove').onclick=()=>{page().items=page().items.filter(i=>i.id!==selected);selected=null;renderItems();persist()};$('#front').onclick=()=>{const i=page().items.find(i=>i.id===selected);if(i){page().items=page().items.filter(x=>x!==i);page().items.push(i);renderItems();persist()}};
$('#export').onclick=async()=>{const button=$('#export');button.disabled=true;button.textContent='正在匯出…';try{await document.fonts.ready;const c=document.createElement('canvas');c.width=1280;c.height=1520;const ctx=c.getContext('2d');ctx.scale(2,2);ctx.fillStyle='#fffdf5';ctx.fillRect(0,0,640,760);ctx.strokeStyle='#b8b09933';ctx.lineWidth=.5;if(page().paper!=='blank'){for(let y=0;y<760;y+=page().paper==='grid'?22:28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(640,y);ctx.stroke()}if(page().paper==='grid')for(let x=0;x<640;x+=22){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,760);ctx.stroke()}}for(const i of page().items){let img,h=42;if(i.type==='photo'){img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=i.src});h=i.w*img.height/img.width+(i.frame==='polaroid'?42:0)}if(i.type==='sticker'){img=await loadImg(svgURI(stickerMarkup(i.name,Math.round(i.w))));h=i.w}if(i.type==='text')h=i.text.split('\n').length*(i.id==='welcome'?54:37.8);ctx.save();ctx.translate(i.x/100*640+i.w/2,i.y/100*760+h/2);ctx.rotate(i.r*Math.PI/180);ctx.translate(-i.w/2,-h/2);if(i.type==='sticker'){ctx.save();ctx.shadowColor='#49391a33';ctx.shadowBlur=2.5;ctx.shadowOffsetX=1.5;ctx.shadowOffsetY=2.5;ctx.drawImage(img,0,0,i.w,i.w);ctx.restore()}else if(img){const pad=i.frame==='polaroid'?10:0;if(pad){ctx.fillStyle='#fff';ctx.fillRect(0,0,i.w,h)}ctx.drawImage(img,pad,pad,i.w-pad*2,h-(pad?42:0))}else if(i.type==='tape'){const t=TAPES[i.color]||TAPES[0],[u]=tapeTile(t.p);ctx.globalAlpha=.82;ctx.fillStyle=t.c;ctx.fillRect(0,0,i.w,42);try{const pat=ctx.createPattern(await loadImg(u),'repeat');if(pat){ctx.fillStyle=pat;ctx.fillRect(0,0,i.w,42)}}catch{}}else{const font=i.id==='welcome'?30:21,ft=FONTS[i.f||0]||FONTS[0];try{await document.fonts.load(`${font}px ${ft.q}`,i.text)}catch{}ctx.font=`${font}px ${ft.f}`;ctx.fillStyle='#4c4439';ctx.textBaseline='top';let line='',y=0;for(const ch of i.text){if(ch==='\n'||ctx.measureText(line+ch).width>i.w){ctx.fillText(line,0,y);y+=font*1.8;line=ch==='\n'?'':ch}else line+=ch}ctx.fillText(line,0,y)}ctx.restore()}if(page().items.some(i=>i.id==='demo')){ctx.fillStyle='#9b917e';ctx.textAlign='center';ctx.font='8px sans-serif';ctx.fillText('Photo: isoyan / Wikimedia Commons / CC BY-SA 3.0',320,751)}const a=document.createElement('a');a.download=(page().title||'旅行手帳')+'.png';a.href=c.toDataURL('image/png');a.click();toast('已匯出這一頁')}catch{toast('匯出失敗，請稍後再試')}finally{button.disabled=false;button.textContent='匯出這一頁 ↗'}};
