render();const request=indexedDB.open('tabi-paper-journal',1);request.onupgradeneeded=()=>request.result.createObjectStore('journal');request.onsuccess=()=>{db=request.result;const r=db.transaction('journal').objectStore('journal').get('main');r.onsuccess=()=>{if(r.result?.pages?.length){state=r.result;let dropped=0;state.pages.forEach(pg=>{const keep=pg.items.filter(i=>!(i.type==='sticker'&&i.tw));dropped+=pg.items.length-keep.length;pg.items=keep});render();if(dropped){persist();toast('已移除 '+dropped+' 個舊的 emoji 貼紙')}}$('#saveStatus').textContent='已儲存在此裝置'};r.onerror=()=>$('#saveStatus').textContent='讀取失敗，請重新開啟'};request.onerror=()=>$('#saveStatus').textContent='無法儲存，請匯出留存';new ResizeObserver(()=>renderItems()).observe($('#paper'));
